<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_once __DIR__ . '/../includes/KundliRepository.php';
requireLogin();
$uid=current_user_id();$profileId=(int)($_GET['profile_id']??0);if($profileId<=0){$s=db()->prepare('SELECT id FROM birth_profiles WHERE user_id=? ORDER BY id DESC LIMIT 1');$s->bind_param('i',$uid);$s->execute();$r=$s->get_result()->fetch_assoc();$s->close();$profileId=(int)($r['id']??0);}
$s=db()->prepare('SELECT p.*,c.* FROM birth_profiles p JOIN kundli_calculations c ON c.birth_profile_id=p.id AND c.user_id=p.user_id WHERE p.id=? AND p.user_id=? ORDER BY c.id DESC LIMIT 1');$s->bind_param('ii',$profileId,$uid);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();if(!$row){http_response_code(404);exit('Kundli not found. Generate it from the birth profile first.');}
$data=(new KundliRepository())->decode($row);$planetary=$data['planetary'];$houses=$data['houses'];$dasha=$data['dasha'];$chart=$data['chart'];function display_value(mixed $v):string{return $v===null||$v===''?'—':e(is_scalar($v)?(string)$v:json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}
$names=is_array($dasha['mahadasha']??null)?array_values($dasha['mahadasha']):[];$ends=is_array($dasha['mahadasha_order']??null)?array_values($dasha['mahadasha_order']):[];$current=null;$today=new DateTimeImmutable('today');foreach($ends as $i=>$end){try{if($today<=new DateTimeImmutable((string)$end)){$current=$i;break;}}catch(Throwable){}}$starts=[];if($names){try{$starts[0]=new DateTimeImmutable((string)($dasha['dasha_start_date']??''));}catch(Throwable){$starts[0]=null;}for($i=1;$i<count($names);$i++){try{$starts[$i]=new DateTimeImmutable((string)($ends[$i-1]??''));}catch(Throwable){$starts[$i]=null;}}}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kundli — ASTROPOP</title><link rel="stylesheet" href="<?=e(APP_BASE_PATH)?>/assets/css/app.css"></head><body><main class="app-shell"><header class="topbar"><a class="brand" href="<?=e(APP_BASE_PATH)?>/dashboard.php">✦ ASTROPOP</a><nav><a href="<?=e(APP_BASE_PATH)?>/dashboard.php">Dashboard</a><a href="<?=e(APP_BASE_PATH)?>/birth/?profile_id=<?=$profileId?>">Birth profile</a><a href="<?=e(APP_BASE_PATH)?>/yogas.php?profile_id=<?=$profileId?>">Yogas</a><a href="<?=e(APP_BASE_PATH)?>/planetary-analysis.php?profile_id=<?=$profileId?>">Analysis</a><a href="<?=e(APP_BASE_PATH)?>/charts.php?profile_id=<?=$profileId?>">Charts</a><a href="<?=e(APP_BASE_PATH)?>/logout.php">Log out</a></nav></header><section class="content-wrap"><div class="section-heading"><p class="eyebrow">VEDIC ASTROLOGY</p><h1><?=e((string)$row['profile_name'])?>'s Kundli</h1><p class="muted"><?=e((string)$row['full_name'])?> · Canonical calculation loaded from MySQL.</p><div class="hero-actions"><a class="button button-primary" href="<?=e(APP_BASE_PATH)?>/yogas.php?profile_id=<?=$profileId?>">Yoga Report</a><a class="button button-secondary" href="<?=e(APP_BASE_PATH)?>/planetary-analysis.php?profile_id=<?=$profileId?>">Planetary Analysis</a><a class="button button-secondary" href="<?=e(APP_BASE_PATH)?>/birth/recalculate.php?profile_id=<?=$profileId?>">Recalculate from API</a></div></div><section class="grid-2"><article class="card"><p class="eyebrow">BIRTH DETAILS</p><div class="detail-grid"><div><span>Date</span><strong><?=e((string)$row['date_of_birth'])?></strong></div><div><span>Time</span><strong><?=display_value($row['time_of_birth'])?></strong></div><div><span>Place</span><strong><?=e((string)($row['location_name']?:$row['birth_place']))?></strong></div><div><span>Coordinates / TZ</span><strong><?=display_value($row['latitude'])?>, <?=display_value($row['longitude'])?> / UTC <?=display_value($row['timezone'])?></strong></div></div></article><article class="card"><p class="eyebrow">CORE CHART</p><div class="detail-grid"><div><span>Lagna</span><strong><?=display_value($row['lagna'])?></strong></div><div><span>Rashi</span><strong><?=display_value($row['rashi'])?></strong></div><div><span>Nakshatra</span><strong><?=display_value($row['nakshatra'])?></strong></div><div><span>Planets</span><strong><?=count($planetary)?></strong></div></div><p class="muted">Saved <?=display_value($row['calculated_at']??null)?> · Engine <?=display_value($row['engine_version']??null)?> · API <?=display_value($row['api_version']??null)?></p></article></section><section class="card"><div class="row-between"><div><p class="eyebrow">PLANETARY POSITIONS</p><h2>Graha details</h2></div><span class="pill pill-success">Database canonical</span></div><div class="table-wrap"><table><thead><tr><th>Planet</th><th>Degree</th><th>Rashi</th><th>House</th><th>Nakshatra</th><th>Lord</th><th>Retro</th></tr></thead><tbody><?php foreach($planetary as $p):?><tr><td><strong><?=display_value($p['full_name']??$p['name']??null)?></strong></td><td><?=display_value($p['local_degree']??null)?></td><td><?=display_value($p['rashi']??null)?></td><td><?=display_value($p['house']??null)?></td><td><?=display_value($p['nakshatra']??null)?><?=isset($p['nakshatra_pada'])?' · Pada '.display_value($p['nakshatra_pada']):''?></td><td><?=display_value($p['lord']??null)?></td><td><?=display_value($p['retrograde']??null)?></td></tr><?php endforeach;?><?php if(!$planetary):?><tr><td colspan="7">No normalized planetary records are stored. Recalculate the Kundli.</td></tr><?php endif;?></tbody></table></div></section><section class="card"><p class="eyebrow">HOUSES</p><h2>House occupancy</h2><div class="house-grid"><?php for($i=1;$i<=12;$i++):$items=$houses[(string)$i]??$houses[$i]??[];?><article><span>House <?=$i?></span><strong><?=$items?e(implode(', ',array_map('strval',$items))):'Empty'?></strong></article><?php endfor;?></div></section><section class="card"><div class="row-between"><div><p class="eyebrow">VIMSHOTTARI DASHA</p><h2>Maha Dasha timeline</h2></div><?php if($current!==null):?><span class="pill pill-success">Current: <?=e((string)$names[$current])?></span><?php endif;?></div><?php if($names&&$ends):?><div class="table-wrap"><table><thead><tr><th>Maha Dasha</th><th>Start</th><th>End</th><th>Status</th></tr></thead><tbody><?php foreach($names as $i=>$name):$cur=$current===$i;?><tr<?=$cur?' class="dasha-current"':''?>><td><strong><?=e((string)$name)?></strong></td><td><?=isset($starts[$i])&&$starts[$i] instanceof DateTimeImmutable?e($starts[$i]->format('d M Y')):'—'?></td><td><?=e((string)($ends[$i]??'—'))?></td><td><?=$cur?'<span class="pill pill-success">Current</span>':'—'?></td></tr><?php endforeach;?></tbody></table></div><div class="detail-grid"><div><span>Dasha start</span><strong><?=display_value($dasha['dasha_start_date']??null)?></strong></div><div><span>Start year</span><strong><?=display_value($dasha['start_year']??null)?></strong></div><div><span>Balance at birth</span><strong><?=display_value($dasha['dasha_remaining_at_birth']??null)?></strong></div></div><?php else:?><p class="muted">Maha Dasha is not stored. Recalculate once from the birth profile.</p><?php endif;?></section><details class="card"><summary><strong>Developer: stored calculation</strong></summary><pre class="api-output"><?=e(json_encode(['lagna'=>$row['lagna'],'rashi'=>$row['rashi'],'nakshatra'=>$row['nakshatra'],'planetary_data'=>$planetary,'house_data'=>$houses,'dasha_data'=>$dasha,'chart_data'=>$chart],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></pre></details></section></main></body></html>
